<?php use App\Support\Helpers; ?>
<h1>Configuración de columnas</h1><?php if ($flash): ?><p class="alert success"><?= Helpers::h($flash) ?></p><?php endif; ?><form method="post" action="/admin/columns"><input type="hidden" name="csrf" value="<?= Helpers::h($csrf) ?>"><div class="column-settings"><?php foreach ($columns as $column): ?><?php $id=(int)$column['id']; ?><fieldset class="column-card"><legend><?= Helpers::h($column['original_name']) ?></legend><p class="muted">Tipo detectado: <?= Helpers::h($column['detected_type']) ?> · <?= $column['present_in_last_import'] ? 'Presente en la última importación' : 'Columna histórica' ?></p><div class="column-controls"><label>Alias<input name="columns[<?= $id ?>][alias]" value="<?= Helpers::h($column['alias']) ?>"></label><label>Tipo manual<select name="columns[<?= $id ?>][manual_type]"><option value="">Automático</option><?php foreach (['text'=>'Texto','integer'=>'Entero','decimal'=>'Decimal','date'=>'Fecha','datetime'=>'Fecha y hora','boolean'=>'Booleano'] as $value=>$label): ?><option value="<?= $value ?>" <?= $column['manual_type']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Formato<input name="columns[<?= $id ?>][display_format]" value="<?= Helpers::h($column['display_format']) ?>" placeholder="Opcional"></label><label>Orden<input type="number" min="0" name="columns[<?= $id ?>][display_order]" value="<?= $column['display_order'] ?>"></label></div><div class="column-toggles"><label class="check"><input type="checkbox" name="columns[<?= $id ?>][visible_table]" <?= $column['visible_table']?'checked':'' ?>> Mostrar en tabla</label><label class="check"><input type="checkbox" name="columns[<?= $id ?>][visible_detail]" <?= $column['visible_detail']?'checked':'' ?>> Mostrar en detalle</label></div></fieldset><?php endforeach; ?></div><button>Guardar cambios</button></form>
